const sx = params.width / 4, sy = params.height / 4.6;
const R = 2.0;
const white = { preset: 'wood', color: params.color, roughness: 0.55 };
const deck = { preset: 'wood', color: params.deckColor, roughness: 0.8 };
const slate = { preset: 'stone', roughness: 0.85, flatShading: true, vertexColors: true };
const iron = { preset: 'metal', color: '#2a2c30', metalness: 0.7, roughness: 0.4 };
function A(m, mat) { m.scale(sx, sy, sx); api.add(m, mat); }
const D = Math.PI / 180;
const ap = R * Math.cos(22.5 * D);
const side = 2 * R * Math.sin(22.5 * D);
// base
A(api.cylinder(R * 1.02, R * 1.02, 0.42, 8).rotate(0, 22.5, 0).translate(0, 0.21, 0), white);
A(api.cylinder(R * 1.08, R * 1.08, 0.08, 8).rotate(0, 22.5, 0).translate(0, 0.46, 0), deck);
// steps
A(api.box(1.4, 0.17, 0.4).translate(0, 0.085, ap * 1.08 + 0.55), deck);
A(api.box(1.2, 0.33, 0.4).translate(0, 0.165, ap * 1.08 + 0.2), deck);
const top = 0.5, Hc = 2.6, beamY = top + Hc;
const profile = [[0, 0], [0.09, 0], [0.09, 0.1], [0.05, 0.16], [0.045, 0.4], [0.065, 0.9], [0.045, 1.5], [0.04, 2.1], [0.055, 2.4], [0.085, 2.47], [0.085, 2.6], [0, 2.6]];
for (let i = 0; i < 8; i++) {
  const a = (i * 45 + 22.5) * D;
  const x = Math.cos(a) * R, z = Math.sin(a) * R;
  A(api.lathe(profile, 12).translate(x, top, z), white);
  api.collider({ kind: 'cylinder', radius: 0.09 * sx, halfHeight: Hc / 2 * sy, offset: [x * sx, (top + Hc / 2) * sy, z * sx] });
}
for (let i = 0; i < 8; i++) {
  const th = i * 45 + 45;
  const t = th * D;
  const cx = Math.cos(t) * ap, cz = Math.sin(t) * ap;
  const phi = -(th + 90);
  // beam
  A(api.box(side + 0.2, 0.2, 0.14).rotate(0, phi, 0).translate(cx, beamY - 0.05, cz), white);
  // brackets
  const L = side / 2 - 0.08;
  const tx = -Math.sin(t), tz = Math.cos(t);
  const b1 = api.extrude([[0, 0], [0.5, 0], [0.08, -0.08], [0, -0.5]], 0.05).rotate(0, phi, 0).translate(cx - tx * L, beamY - 0.15, cz - tz * L);
  const b2 = api.extrude([[0, 0], [0, -0.5], [-0.08, -0.08], [-0.5, 0]], 0.05).rotate(0, phi, 0).translate(cx + tx * L, beamY - 0.15, cz + tz * L);
  A(b1, white); A(b2, white);
  A(api.sphere(0.04, 1).rotate(0, 0, 0).translate(cx - tx * (L - 0.22) , beamY - 0.3, cz - tz * (L - 0.22)), white);
  A(api.sphere(0.04, 1).translate(cx + tx * (L - 0.22), beamY - 0.3, cz + tz * (L - 0.22)), white);
  if (i === 1) continue;
  // railing
  const rl = side - 0.15;
  const rb = top + 0.08;
  A(api.box(rl, 0.07, 0.07).rotate(0, phi, 0).translate(cx, rb + 0.12, cz), white);
  A(api.box(rl, 0.09, 0.1).rotate(0, phi, 0).translate(cx, rb + 0.9, cz), white);
  const n = params.balusters;
  for (let k = 0; k < n; k++) {
    const u = ((k + 0.5) / n - 0.5) * (rl - 0.1);
    A(api.cylinder(0.022, 0.022, 0.8, 6).translate(cx + tx * u, rb + 0.5, cz + tz * u), white);
  }
}
// roof
const rr = R * 1.25, y0 = beamY + 0.05, rise = 1.1;
const prof = [[0, y0], [rr, y0], [rr, y0 + 0.06]];
for (let k = 1; k <= 14; k++) {
  const t = k / 14;
  prof.push([rr * Math.pow(1 - t, 1.15) + 0.0001, y0 + 0.06 + rise * t - 0.18 * Math.sin(t * Math.PI)]);
}
const roof = api.lathe(prof, 8).rotate(0, 22.5, 0);
const c1 = params.roofColor, c2 = api.mix(params.roofColor, '#15181c', 0.35);
roof.vertexColor((x, y, z) => (Math.floor((y - y0) / 0.13) % 2 === 0 ? c1 : c2));
A(roof, slate);
A(api.cylinder(0.3, 0.3, 0.1, 8).translate(0, y0 + rise + 0.05, 0), white);
// finial
const yt = y0 + 0.06 + rise;
A(api.sphere(0.1, 2).translate(0, yt + 0.1, 0), white);
A(api.cylinder(0.015, 0.015, 0.4, 6).translate(0, yt + 0.3, 0), iron);
A(api.box(0.4, 0.03, 0.03).translate(0, yt + 0.35, 0), iron);
A(api.cone(0.05, 0.12, 6).rotate(0, 0, -90).translate(0.26, yt + 0.35, 0), iron);
A(api.box(0.1, 0.1, 0.01).translate(-0.2, yt + 0.37, 0), iron);
// colliders
api.collider({ kind: 'cylinder', radius: R * 1.05 * sx, halfHeight: 0.25 * sy, offset: [0, 0.25 * sy, 0] });
api.collider({ kind: 'box', halfExtents: [0.7 * sx, 0.165 * sy, 0.2 * sx], offset: [0, 0.165 * sy, (ap * 1.08 + 0.2) * sx] });
return api.build();
